CREATE TABLE "form_versions" (
	"version" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "form_versions_version_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 3 CACHE 1),
	"config" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
