INSERT INTO "form_versions" ("version", "config") VALUES (2, '{"title":"Global User Research Questionnaire","description":"Help us understand how you save, invest, and discover global investment opportunities.","questions":[{"id":"email","type":"email","label":"What''s your email address?","placeholder":"you@example.com","required":true},{"id":"country","type":"dropdown","label":"Which country do you live in?","required":true,"options":["Afghanistan","Åland Islands","Albania","Algeria","American Samoa","Andorra","Angola","Anguilla","Antarctica","Antigua & Barbuda","Argentina","Armenia","Aruba","Australia","Austria","Azerbaijan","Bahamas","Bahrain","Bangladesh","Barbados","Belarus","Belgium","Belize","Benin","Bermuda","Bhutan","Bolivia","Bosnia & Herzegovina","Botswana","Bouvet Island","Brazil","British Indian Ocean Territory","British Virgin Islands","Brunei","Bulgaria","Burkina Faso","Burundi","Cambodia","Cameroon","Canada","Cape Verde","Caribbean Netherlands","Cayman Islands","Central African Republic","Chad","Chile","China","Christmas Island","Cocos (Keeling) Islands","Colombia","Comoros","Congo - Brazzaville","Congo - Kinshasa","Cook Islands","Costa Rica","Côte d’Ivoire","Croatia","Cuba","Curaçao","Cyprus","Czechia","Denmark","Djibouti","Dominica","Dominican Republic","Ecuador","Egypt","El Salvador","Equatorial Guinea","Eritrea","Estonia","Eswatini","Ethiopia","Falkland Islands","Faroe Islands","Fiji","Finland","France","French Guiana","French Polynesia","French Southern Territories","Gabon","Gambia","Georgia","Germany","Ghana","Gibraltar","Greece","Greenland","Grenada","Guadeloupe","Guam","Guatemala","Guernsey","Guinea","Guinea-Bissau","Guyana","Haiti","Heard & McDonald Islands","Honduras","Hong Kong SAR China","Hungary","Iceland","India","Indonesia","Iran","Iraq","Ireland","Isle of Man","Israel","Italy","Jamaica","Japan","Jersey","Jordan","Kazakhstan","Kenya","Kiribati","Kuwait","Kyrgyzstan","Laos","Latvia","Lebanon","Lesotho","Liberia","Libya","Liechtenstein","Lithuania","Luxembourg","Macao SAR China","Madagascar","Malawi","Malaysia","Maldives","Mali","Malta","Marshall Islands","Martinique","Mauritania","Mauritius","Mayotte","Mexico","Micronesia","Moldova","Monaco","Mongolia","Montenegro","Montserrat","Morocco","Mozambique","Myanmar (Burma)","Namibia","Nauru","Nepal","Netherlands","New Caledonia","New Zealand","Nicaragua","Niger","Nigeria","Niue","Norfolk Island","North Korea","North Macedonia","Northern Mariana Islands","Norway","Oman","Pakistan","Palau","Palestinian Territories","Panama","Papua New Guinea","Paraguay","Peru","Philippines","Pitcairn Islands","Poland","Portugal","Puerto Rico","Qatar","Réunion","Romania","Russia","Rwanda","Samoa","San Marino","São Tomé & Príncipe","Saudi Arabia","Senegal","Serbia","Seychelles","Sierra Leone","Singapore","Sint Maarten","Slovakia","Slovenia","Solomon Islands","Somalia","South Africa","South Georgia & South Sandwich Islands","South Korea","South Sudan","Spain","Sri Lanka","St. Barthélemy","St. Helena","St. Kitts & Nevis","St. Lucia","St. Martin","St. Pierre & Miquelon","St. Vincent & Grenadines","Sudan","Suriname","Svalbard & Jan Mayen","Sweden","Switzerland","Syria","Taiwan","Tajikistan","Tanzania","Thailand","Timor-Leste","Togo","Tokelau","Tonga","Trinidad & Tobago","Tunisia","Türkiye","Turkmenistan","Turks & Caicos Islands","Tuvalu","U.S. Outlying Islands","U.S. Virgin Islands","Uganda","Ukraine","United Arab Emirates","United Kingdom","United States","Uruguay","Uzbekistan","Vanuatu","Vatican City","Venezuela","Vietnam","Wallis & Futuna","Western Sahara","Yemen","Zambia","Zimbabwe"]},{"id":"age_range","type":"multiple_choice","label":"Age range","required":true,"options":["18–24","25–34","35–44","45+"]},{"id":"occupation","type":"multiple_choice","label":"What do you do?","required":true,"options":["Student","Salaried","Freelancer / remote","Business owner","Other"]},{"id":"where_invest","type":"multi_select","label":"Where do you currently save or invest your money today?","description":"Select all that apply","required":true,"options":["Bank savings or fixed deposits","Local stocks or funds","Foreign stocks","US dollars (cash or account)","Stablecoins or other crypto","Gold or real estate","I don''t save or invest"]},{"id":"monthly_savings","type":"multiple_choice","label":"Approximately how much do you invest or save each month?","required":true,"options":["Less than $50","$50–$200","$200–$500","$500–$1,000","More than $1,000","Prefer not to say"]},{"id":"savings_concerns","type":"multi_select","label":"What concerns you most about your savings and investments?","description":"Select up to 2","maxSelections":2,"required":true,"options":["Inflation reducing my purchasing power","My local currency losing value against the USD","Poor returns from local investments","Limited access to international investments","Not knowing what to invest in","Risk of losing money","Nothing in particular","Other"]},{"id":"invested_foreign","type":"multiple_choice","label":"Have you ever considered investing in foreign companies, currencies, or assets?","required":true,"options":["Yes, and I currently invest internationally","Yes, but I stopped investing internationally","Yes, but I''ve never actually invested","No, I''ve never considered it"]},{"id":"international_challenges","type":"multi_select","label":"What has been your biggest challenge with international investing?","description":"Select up to 2","maxSelections":2,"required":true,"options":["Don''t know how or where to start","Complicated onboarding or funding process","High fees / currency conversion costs","Tax or regulatory uncertainty","Don''t know which international assets to invest in","Don''t trust available platforms","No major challenges","Never been interested in international investing"]},{"id":"investment_research","type":"multi_select","label":"How do you currently decide what to invest in?","description":"Select up to 2","maxSelections":2,"required":true,"options":["Research individual companies myself","Follow financial creators / influencers","Recommendations from friends or family","Financial advisors / investment professionals","Invest in index funds or ready-made portfolios","AI tools like ChatGPT","I don''t actively research investments"]},{"id":"theme_investing","type":"multiple_choice","label":"Imagine you believe AI, EVs, or another industry will grow significantly. How would you prefer to invest?","required":true,"options":["Pick individual companies myself","Select an industry and let an app suggest relevant companies","Invest in an existing index fund or ETF","Have an AI assistant construct a portfolio based on my views and risk appetite","I wouldn''t invest based on industry trends"]},{"id":"interest_area","type":"multiple_choice","label":"Which part of this app would interest you the most?","description":"Imagine an app that helps you invest globally. You can save in dollars, invest in international companies, or explore trends like AI, EVs, and healthcare. The app helps you create an AI wealth manager to discover relevant investments and suggest portfolios based on your personal interests and risk appetite.\n\nChoose one.","required":true,"options":["Saving in USD or other foreign currencies","Investing in global companies like Apple, Nvidia, or Tesla","Investing in global index funds / ETFs","Discovering investment opportunities based on themes I believe in","Having AI suggest and manage a personalised portfolio","None of these"]},{"id":"ai_comfort","type":"multiple_choice","label":"How comfortable would you be letting AI help with your investments?","required":true,"options":["Comfortable using AI for research only","Comfortable receiving AI-generated investment recommendations","Comfortable letting AI build a portfolio that I approve","Comfortable letting AI execute investments within limits I set","Not comfortable using AI for investing"]},{"id":"trust_factors","type":"multi_select","label":"What would make you trust a new global investment app?","description":"Select up to 2","maxSelections":2,"required":true,"options":["Regulatory approval / compliance","Partnerships with established banks or financial institutions","Transparent fees and investment risks","Clear information about asset ownership and custody","Recommendations from people I trust","Ability to withdraw my money easily","Strong brand reputation"]},{"id":"investing_frequency","type":"multiple_choice","label":"If you started investing internationally, how would you prefer to invest?","required":true,"options":["Small amounts daily","Small amounts weekly","A fixed amount monthly","Larger amounts whenever I have extra money","I wouldn''t invest internationally"]},{"id":"discovery_channels","type":"multi_select","label":"Where do you usually discover new financial products or investment opportunities?","description":"Select up to 2","maxSelections":2,"required":true,"options":["Instagram / TikTok / YouTube","X / Reddit / online communities","Friends / colleagues / family","Financial news / blogs / newsletters","Financial advisors / banks","App stores / online search","Other"]},{"id":"adoption_hesitation","type":"long_text","label":"What is the biggest reason you might hesitate to try an app like this?","required":true}]}'::jsonb);
